            "Microsoft.EntityFrameworkCore.SqlServer" => "IF OBJECT_ID(N'[dbo].[VolunteerDonations]', N'U') IS NULL CREATE TABLE [dbo].[VolunteerDonations] ([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY, [DonorName] nvarchar(150) NOT NULL, [Phone] nvarchar(32) NOT NULL, [Email] nvarchar(254) NULL, [Categories] nvarchar(300) NOT NULL, [ItemsDescription] nvarchar(1500) NOT NULL, [CollectionCenter] nvarchar(200) NOT NULL, [Status] nvarchar(20) NOT NULL, [PickupRequested] bit NOT NULL DEFAULT 0, [AssignedVolunteerId] int NULL, [AssignedVolunteerName] nvarchar(150) NULL, [AcceptedAt] datetime2 NULL, [DeliveredAt] datetime2 NULL, [CreatedAt] datetime2 NOT NULL); IF COL_LENGTH('dbo.VolunteerDonations', 'Email') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [Email] nvarchar(254) NULL; IF COL_LENGTH('dbo.VolunteerDonations', 'PickupRequested') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [PickupRequested] bit NOT NULL CONSTRAINT [DF_VolunteerDonations_PickupRequested] DEFAULT 0; IF COL_LENGTH('dbo.VolunteerDonations', 'AssignedVolunteerId') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [AssignedVolunteerId] int NULL; IF COL_LENGTH('dbo.VolunteerDonations', 'AssignedVolunteerName') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [AssignedVolunteerName] nvarchar(150) NULL; IF COL_LENGTH('dbo.VolunteerDonations', 'AcceptedAt') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [AcceptedAt] datetime2 NULL; IF COL_LENGTH('dbo.VolunteerDonations', 'DeliveredAt') IS NULL ALTER TABLE [dbo].[VolunteerDonations] ADD [DeliveredAt] datetime2 NULL; IF OBJECT_ID(N'[dbo].[VolunteerMissionAssignments]', N'U') IS NULL CREATE TABLE [dbo].[VolunteerMissionAssignments] ([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY, [EmergencyRequestId] int NOT NULL, [VolunteerAccountId] int NOT NULL, [VolunteerName] nvarchar(150) NOT NULL, [Status] nvarchar(20) NOT NULL, [ClaimedAt] datetime2 NOT NULL, [CompletedAt] datetime2 NULL); IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_VolunteerMissionAssignments_EmergencyRequestId') CREATE UNIQUE INDEX [IX_VolunteerMissionAssignments_EmergencyRequestId] ON [dbo].[VolunteerMissionAssignments] ([EmergencyRequestId]);",
            "Npgsql.EntityFrameworkCore.PostgreSQL" => "CREATE TABLE IF NOT EXISTS \"VolunteerDonations\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"DonorName\" varchar(150) NOT NULL, \"Phone\" varchar(32) NOT NULL, \"Email\" varchar(254) NULL, \"Categories\" varchar(300) NOT NULL, \"ItemsDescription\" varchar(1500) NOT NULL, \"CollectionCenter\" varchar(200) NOT NULL, \"Status\" varchar(20) NOT NULL, \"PickupRequested\" boolean NOT NULL DEFAULT FALSE, \"AssignedVolunteerId\" integer NULL, \"AssignedVolunteerName\" varchar(150) NULL, \"AcceptedAt\" timestamp with time zone NULL, \"DeliveredAt\" timestamp with time zone NULL, \"CreatedAt\" timestamp with time zone NOT NULL); ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"Email\" varchar(254) NULL; ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"PickupRequested\" boolean NOT NULL DEFAULT FALSE; ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"AssignedVolunteerId\" integer NULL; ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"AssignedVolunteerName\" varchar(150) NULL; ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"AcceptedAt\" timestamp with time zone NULL; ALTER TABLE \"VolunteerDonations\" ADD COLUMN IF NOT EXISTS \"DeliveredAt\" timestamp with time zone NULL; CREATE TABLE IF NOT EXISTS \"VolunteerMissionAssignments\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"EmergencyRequestId\" integer NOT NULL, \"VolunteerAccountId\" integer NOT NULL, \"VolunteerName\" varchar(150) NOT NULL, \"Status\" varchar(20) NOT NULL, \"ClaimedAt\" timestamp with time zone NOT NULL, \"CompletedAt\" timestamp with time zone NULL); CREATE UNIQUE INDEX IF NOT EXISTS \"IX_VolunteerMissionAssignments_EmergencyRequestId\" ON \"VolunteerMissionAssignments\" (\"EmergencyRequestId\");",
            _ => "CREATE TABLE IF NOT EXISTS \"VolunteerDonations\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_VolunteerDonations\" PRIMARY KEY AUTOINCREMENT, \"DonorName\" TEXT NOT NULL, \"Phone\" TEXT NOT NULL, \"Email\" TEXT NULL, \"Categories\" TEXT NOT NULL, \"ItemsDescription\" TEXT NOT NULL, \"CollectionCenter\" TEXT NOT NULL, \"Status\" TEXT NOT NULL, \"PickupRequested\" INTEGER NOT NULL DEFAULT 0, \"AssignedVolunteerId\" INTEGER NULL, \"AssignedVolunteerName\" TEXT NULL, \"AcceptedAt\" TEXT NULL, \"DeliveredAt\" TEXT NULL, \"CreatedAt\" TEXT NOT NULL); CREATE TABLE IF NOT EXISTS \"VolunteerMissionAssignments\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_VolunteerMissionAssignments\" PRIMARY KEY AUTOINCREMENT, \"EmergencyRequestId\" INTEGER NOT NULL, \"VolunteerAccountId\" INTEGER NOT NULL, \"VolunteerName\" TEXT NOT NULL, \"Status\" TEXT NOT NULL, \"ClaimedAt\" TEXT NOT NULL, \"CompletedAt\" TEXT NULL); CREATE UNIQUE INDEX IF NOT EXISTS \"IX_VolunteerMissionAssignments_EmergencyRequestId\" ON \"VolunteerMissionAssignments\" (\"EmergencyRequestId\");"
        };

        await db.Database.ExecuteSqlRawAsync(sql, cancellationToken);

