                ("PickupRequested", "ALTER TABLE \"VolunteerDonations\" ADD COLUMN \"PickupRequested\" INTEGER NOT NULL DEFAULT 0"),
                ("AssignedVolunteerId", "ALTER TABLE \"VolunteerDonations\" ADD COLUMN \"AssignedVolunteerId\" INTEGER NULL"),
                ("AssignedVolunteerName", "ALTER TABLE \"VolunteerDonations\" ADD COLUMN \"AssignedVolunteerName\" TEXT NULL"),
                ("AcceptedAt", "ALTER TABLE \"VolunteerDonations\" ADD COLUMN \"AcceptedAt\" TEXT NULL"),
                ("DeliveredAt", "ALTER TABLE \"VolunteerDonations\" ADD COLUMN \"DeliveredAt\" TEXT NULL")
            };
            foreach (var column in additions)
